// === Tab: mySketch ===
var w=0 // Width of each blocks
var s=0 // Spacing between those blocks
var maxYears=80

function setup() {
	createCanvas(windowWidth, windowHeight)
	background(255)
	stroke(0)
	strokeWeight(1)
	noFill()
	w=(height/maxYears)*0.6
	s=w/2
}

function draw() {
	translate(width/2-(w+s)*26,height/2-(w+s)*maxYears/2)

	for (let years=0; years<maxYears; years++) {
		for (let weeks=0; weeks<52; weeks++) {
			rect(0,0,w,w)
			translate(w+s,0)
		}
		translate(-w*52-s*52,w+s)
	}
}
